// Mark a state the test has reached as the app's rendering of a mockup frame.
//
// The mockup boards (docs/mockups/*.dc.html) draw each workflow on two phones,
// a tablet and a computer; e2e/web/lib/mockup-frames.json lists every frame
// (board, index, device kind, the board's caption), generated by
// audit/render-mockups.mjs, which also renders the boards themselves. A spec
// calls
//
//   await mockup(page, 'W02-find-and-play', 1);
//
// at the moment the app shows what that frame draws. Normally this does
// nothing. With ESTANTE_E2E_MOCKUPS=<dir> set, and only in the project whose
// device matches the frame (a phone frame from the phone project), it resizes
// the viewport to the frame's inner size, screenshots the app in Estante
// (light) and in Palco (dark) — the automatic theme follows the device's mode
// — restores the viewport and colour scheme, and appends a manifest line, so
// the app's screenshot and the rendered board frame can be compared pairwise
// (<dir>/<theme>/<Board>--<n>-<kind>.png, the renderer's own file names).
//
// Purely observational: it changes nothing the app holds, and a spec's own
// assertions never depend on it.

import { appendFileSync, mkdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { test } from '@playwright/test';

const FRAMES = JSON.parse(readFileSync(new URL('./mockup-frames.json', import.meta.url), 'utf8'));

const OUT = process.env.ESTANTE_E2E_MOCKUPS || '';

// The boards' device frames, inside their rims (docs/mockups/theme.css .dev.*).
const SIZE = {
  phone: { width: 370, height: 824 },
  tablet: { width: 792, height: 1152 },
  desktop: { width: 1264, height: 784 },
};
// Playwright project → the board device kind it renders.
const KIND_OF_PROJECT = { phone: 'phone', tablet: 'tablet', computer: 'desktop' };

const THEMES = [
  { theme: 'estante', colorScheme: 'light' },
  { theme: 'palco', colorScheme: 'dark' },
];

export async function mockup(page, board, index, { note = '' } = {}) {
  const frame = FRAMES.find((f) => f.board === board && f.index === index);
  if (!frame) throw new Error(`mockup: no frame ${board} #${index} in mockup-frames.json`);
  if (!OUT) return;
  const info = test.info();
  if (KIND_OF_PROJECT[info.project.name] !== frame.kind) return;

  const file = `${board}--${index}-${frame.kind}.png`;
  const before = page.viewportSize();
  await page.setViewportSize(SIZE[frame.kind]);
  try {
    for (const { theme, colorScheme } of THEMES) {
      await page.emulateMedia({ colorScheme });
      await page.waitForTimeout(250); // layout and theme settle after the resize
      mkdirSync(join(OUT, theme), { recursive: true });
      // CSS pixels, so the app's frame is the size of the rendered board frame.
      await page.screenshot({ path: join(OUT, theme, file), scale: 'css' });
      const rootTheme = await page
        .locator('.est')
        .first()
        .getAttribute('class')
        .catch(() => '');
      appendFileSync(
        join(OUT, 'manifest.jsonl'),
        `${JSON.stringify({
          board,
          index,
          kind: frame.kind,
          label: frame.label,
          theme,
          appliedTheme: /theme-(\w+)/.exec(rootTheme ?? '')?.[1] ?? null,
          png: `${theme}/${file}`,
          spec: info.file.split('/tests/').pop(),
          test: info.title,
          url: page.url(),
          note,
        })}\n`,
      );
    }
  } finally {
    await page.emulateMedia({ colorScheme: null });
    if (before) await page.setViewportSize(before);
  }
}
